p { color: black; }
.note { color: blue; }
p.note { color: green; }   /* wins: more specific than .note */

.card { width: 300px; padding: 20px; border: 1px solid; }
/* Default content-box: total width = 300 + 40 + 2 = 342px */

*, *::before, *::after { box-sizing: border-box; }
/* border-box: total width = 300px, and content shrinks to 258px */

/* A header: logo on the left, actions on the right */
.header { display: flex; justify-content: space-between; align-items: center; gap: 1rem; }

/* Cards that wrap onto new lines */
.tags { display: flex; flex-wrap: wrap; gap: .5rem; }

/* Sidebar fixed; main content fills the rest */
.layout { display: flex; }
.sidebar { flex: 0 0 240px; }
.content { flex: 1; min-width: 0; }

/* Header, sidebar, content and footer */
.page {
  display: grid;
  grid-template-columns: 240px 1fr;
  grid-template-rows: auto 1fr auto;
  min-height: 100dvh;
}
.page > header, .page > footer { grid-column: 1 / -1; }

/* Responsive cards, with no media queries */
.cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: 1rem;
}

*, *::before, *::after { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, sans-serif; }

.app {
  display: grid;
  grid-template-columns: 1fr;
  grid-template-areas:
    "top"
    "main";
  min-height: 100dvh;
}
.topbar  { grid-area: top; display: flex; align-items: center; gap: 1rem; padding: .75rem 1rem; }
.content { grid-area: main; min-width: 0; padding: 1rem; }
.sidebar { display: none; }

@media (min-width: 768px) {
  .app {
    grid-template-columns: 240px 1fr;
    grid-template-areas:
      "top  top"
      "side main";
  }
  .sidebar { display: block; grid-area: side; padding: 1rem; }
  .menu { display: none; }
}

.stats {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: 1rem;
  margin-bottom: 1rem;
}
.stat { padding: 1rem; border: 1px solid #ddd; border-radius: .5rem; }
.stat h2 { margin: 0; font-size: .875rem; font-weight: 500; }
.stat p  { margin: .25rem 0 0; font-size: 1.5rem; font-weight: 700; }

.table-wrap { overflow-x: auto; }        /* the table scrolls, not the page */
table { width: 100%; border-collapse: collapse; }
th, td { padding: .5rem .75rem; text-align: left; border-bottom: 1px solid #ddd; white-space: nowrap; }

:root {
  --bg: #ffffff;
  --text: #1f2937;
  --border: #e5e7eb;
  --accent: #4f46e5;
}
@media (prefers-color-scheme: dark) {
  :root:not([data-theme="light"]) {
    --bg: #111827;
    --text: #f3f4f6;
    --border: #374151;
    --accent: #818cf8;
  }
}
:root[data-theme="dark"] {
  --bg: #111827;
  --text: #f3f4f6;
  --border: #374151;
  --accent: #818cf8;
}
body { background: var(--bg); color: var(--text); }

try {
  document.documentElement.dataset.theme = localStorage.getItem('theme') ?? '';
} catch {
  // storage blocked: the system preference still applies
}

.drawer { transition: transform .2s ease; }

@media (prefers-reduced-motion: reduce) {
  .drawer { transition: none; }
}

